code="from pathlib import Path\nimport ast,json,hashlib\nA=Path('/vllm-workspace/vllm-ascend/vllm_ascend');specs=[(A/'attention/dsa_v41.py','3505769857f83fa7e67f652984f50bd0478158f1d24f185cab091203e70392fd','count_uses'),(A/'attention/context_parallel/dsa_v41_cp.py','039ec9d18e0a8a4aa39f9d5b4bea15204cea3f397a3fce97a5097b266bc9822e','CP_forward'),(A/'attention/dsa_v1.py',None,'wrapper'),(A/'worker/device_metadata.py','efe13f0e801b70d7fba7498ac44062a8eccfd78e5b6303cf658d33dd22217580','lifetime')];out=[]\nfor p,expected,mode in specs:\n b=p.read_bytes();sha=hashlib.sha256(b).hexdigest()\n if expected is not None:assert sha==expected\n ls=b.decode().splitlines();t=ast.parse(b.decode());par={ch:z for z in ast.walk(t)for ch in ast.iter_child_nodes(z)};ff=[];ss={}\n def src(s,e):return[str(j+1)+': '+ls[j]for j in range(s-1,e)]\n def function_at(line):return min((f for f in ast.walk(t)if isinstance(f,ast.FunctionDef)and f.lineno<=line<=f.end_lineno),key=lambda f:f.end_lineno-f.lineno)\n def collect(z):\n  q=z;stmt=None;guards=[]\n  while q in par:\n   parent=par[q]\n   if stmt is None and isinstance(q,(ast.Assign,ast.AnnAssign,ast.Expr,ast.Return)):stmt=q\n   if isinstance(parent,ast.If):guards.append(dict(line=parent.lineno,test=ast.unparse(parent.test),arm='BODY'if q in parent.body else'ORELSE'if q in parent.orelse else'TEST'))\n   if isinstance(parent,ast.FunctionDef):break\n   q=parent\n  if stmt is None:return\n  assert stmt.end_lineno-stmt.lineno<100;ss[stmt.lineno]=dict(start=stmt.lineno,end=stmt.end_lineno,source=src(stmt.lineno,stmt.end_lineno),guards=guards)\n if mode=='count_uses':\n  f=function_at(1116)\n  for z in ast.walk(f):\n   if isinstance(z,ast.Name)and z.id=='ori_topk_length':collect(z)\n elif mode=='CP_forward':\n  f=function_at(166)\n  for z in ast.walk(f):\n   if(isinstance(z,ast.Constant)and isinstance(z.value,str)and('sparse_indices'in z.value or'topk_length'in z.value))or(isinstance(z,ast.Attribute)and z.attr in['ori_sparse_indices','ori_topk_length','indices','swa']):collect(z)\n elif mode=='wrapper':\n  f=function_at(474);assert f.name=='build_dspark_swa_indices'and f.end_lineno-f.lineno<190;ff.append(dict(name=f.name,start=f.lineno,end=f.end_lineno,source=src(f.lineno,f.end_lineno)))\n elif mode=='lifetime':\n  cls=next(c for c in t.body if isinstance(c,ast.ClassDef)and c.name=='DeviceMetadataExecutor')\n  for name in['wait','release']:\n   f=next(f for f in cls.body if isinstance(f,ast.FunctionDef)and f.name==name);assert f.end_lineno-f.lineno<100;ff.append(dict(name=f.name,start=f.lineno,end=f.end_lineno,source=src(f.lineno,f.end_lineno)))\n out.append(dict(path=str(p),sha256=sha,functions=ff,statements=list(ss.values())))\nassert sum(sum(len(q['source'])for q in f['functions']+f['statements'])for f in out)<650\nprint(json.dumps(dict(files=out,scope='SWA kernel already outputs length; only actual count uses/CP forwarding/wrapper width formula and executor wait-release to judge reuse, not a new producer claim.',no_model_or_torch_import=True)))\n"
